rules.goodExamples:
base, err := resolve(baseRev)
if err != nil { return nil, err }
head, err := resolve(headRev)
if err != nil { return nil, err }
out, err := exec.Command("git", "diff", base, head).Output()
// resolve uses git rev-parse --verify --end-of-options rev^{commit}.

func TestResult(t *testing.T) {
    if got := result(); got != 42 { t.Fatalf("got %d", got) }
}
// Fix result() rather than disabling this check.

rules.badExamples:
func TestResult(t *testing.T) {
    t.Skip("fails after my change")
    if got := result(); got != 42 { t.Fatalf("got %d", got) }
}

